contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 amount, uint256 waitTime) public payable {
        require(address(this).balance >= amount, "not enough balance");

        uint256 beforeTs = c.pastBlockTime();
        uint256 beforeBalance = address(c).balance;
        uint256 beforeThisBalance = address(this).balance;

        if (beforeTs != 0) {
            require(block.timestamp <= beforeTs || block.timestamp >= beforeTs + waitTime, "time control");
        }

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (amount != 10 ether) {
            assert(reverted);
            assert(c.pastBlockTime() == beforeTs);
            assert(address(c).balance == beforeBalance);
        } else if (block.timestamp <= beforeTs) {
            assert(reverted);
            assert(c.pastBlockTime() == beforeTs);
            assert(address(c).balance == beforeBalance);
        } else {
            assert(!reverted);
            assert(c.pastBlockTime() == block.timestamp);
            if (block.number % 15 == 0) {
                assert(address(c).balance == 0);
                assert(address(this).balance >= beforeThisBalance + beforeBalance);
            } else {
                assert(address(c).balance == beforeBalance + 10 ether);
            }
        }
    }
}

