contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, uint64 timestamp) public payable {
        require(amount == 10 ether, "amount must be exactly 10 ether");
        require(address(this).balance >= amount, "not enough balance");
        require(timestamp > c.pastBlockTime(), "timestamp must advance");

        uint beforeBalance = address(c).balance;
        bool reverted;

        // The fallback ignores calldata and uses block.timestamp, so setting
        // the tx timestamp is impossible here; exercise the normal path only.
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            if (block.number % 15 != 0) {
                assert(address(c).balance == beforeBalance + amount);
            } else {
                // On the payable branch the full balance is sent to the caller.
                assert(address(c).balance == 0);
            }
        } else {
            assert(address(c).balance == beforeBalance);
        }
    }

    receive() external payable {}
}

