        // mutating entry point. Fresh contract: before == 0, so any send works.
        (bool ok0, ) = address(c).call{value: 10 ether}(abi.encodeWithSignature("fallback()"));
        assert(ok0);
        uint256 afterFirst = c.pastBlockTime();
