            assert(address(c).balance >= 10 ether || address(c).balance == 0);
        } else {
            assert(c.pastBlockTime() == afterFirst);
        }

        // If a second call is not attempted, the state remains the stored timestamp.
        assert(c.pastBlockTime() == afterFirst || c.pastBlockTime() > afterFirst);
    }

    receive() external payable {}
}

