        // Ensure the stored timestamp is behind the current block time so that
        // the timestamp precondition can actually hold for this transaction.
        // A zero-value call is made until the stored value is strictly less
        // than block.timestamp. Each such call reverts, leaving state intact,
        // until the condition is satisfiable by pasting c's own fallback.
        while (!(block.timestamp > c.pastBlockTime())) {
            try c.call{value: 0}("") {
                // impossible for a zero-value call to succeed
            } catch {
            }
            // Cannot change stored pastBlockTime without a successful 10 ether
            // call, so the only way to satisfy the precondition is to rely on a
            // fresh deployment or prior successful call. Break out to avoid an
            // infinite loop; the assertion below still tests the general rule.
            break;
        }

        uint balanceBefore = address(c).balance;
        uint pastBefore = c.pastBlockTime();
        uint tsNow = block.timestamp;

        bool reverted;
        try c.call{value: amount}("") {
