        bool blockDivisible = block.number % 15 == 0;
        bool expectedSuccess = amountOk && timestampOk && blockDivisible;

        // General rule: the fallback succeeds exactly when all three conditions hold;
        // otherwise it must revert.
        assert(reverted == !expectedSuccess);

        // On success, the contract's entire prior balance plus the sent amount
        // must be transferred to the caller (this test contract).
        if (!reverted) {
            assert(address(c).balance == 0);
            assert(address(this).balance == balanceBefore + amount);
        }
    }

    receive() external payable {}
}

