contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 timeGap) public payable {
        require(timeGap > 0, "timeGap must be positive");
        require(address(this).balance >= 10 ether, "need 10 ether");

        uint256 before = c.pastBlockTime();
        uint256 nextTime = before + timeGap;
        require(nextTime > before, "nextTime must exceed before");

        // Set pastBlockTime to nextTime if it is in the future for the current block,
        // so the deciding call below has block.timestamp <= pastBlockTime and must revert.
        bool canSetFuture = nextTime > block.timestamp;
        if (canSetFuture) {
            uint256 gap = nextTime - block.timestamp + 1;
            if (gap == 1) {
                // Current block.timestamp still unchanged within this transaction.
                // nextTime == block.timestamp + 1, so no same-block call can advance it.
                // The deciding call will still have block.timestamp <= pastBlockTime.
            }
        }

        // The only state-changing call on c in this test; it either succeeds or reverts.
        bool reverted;
        try c.fallback{value: 10 ether}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTime = c.pastBlockTime();

        // For any non-reverting call, the timestamp must have been strictly greater than
        // the previous pastBlockTime, and pastBlockTime must now equal that timestamp.
        assert(!reverted => (promote(block.timestamp) > before && afterTime == block.timestamp));

        // A call must revert exactly when the current block.timestamp does not exceed
        // the stored pastBlockTime.
        assert(reverted == !(block.timestamp > before));
    }

    function promote(uint256 x) private pure returns (uint256) {
        return x;
    }
}

