                staleReverted = false;
            } catch {
                staleReverted = true;
            }
        } else {
            staleReverted = true;
        }

        // The only successful path requires exactly 10 ether and a timestamp strictly greater
        // than the stored pastBlockTime. We check the state transition about pastBlockTime:
        // after a successful 10-ether call, the stored time must be strictly greater than beforeTime.
        uint timestampBefore = block.timestamp;
        bool successReverted;
        try c.fallback{value: amount}() {
            successReverted = false;
        } catch {
            successReverted = true;
        }

        uint afterTime = c.pastBlockTime();

        assert(
            (successReverted && afterTime == beforeTime) ||
            (!successReverted && afterTime > beforeTime)
        );
    }

    receive() external payable {}

    fallback() external payable {}
}

